public static int maximumTH(int[] r, int von, int bis) {
    if (von == bis) {
        return r[von];
    }
    int mitte = (von + bis) / 2;
    int links = maximumTH(r, von, mitte);
    int rechts = maximumTH(r, mitte + 1, bis);
    if (links > rechts) {
        return links;
    }
    return rechts;
}

public static int zerlege(int[] r, int lo, int hi) {
    int pivot = r[lo];
    int grenze = lo;
    for (int i = lo + 1; i <= hi; i++) {
        if (r[i] < pivot) {
            grenze++;
            int h = r[grenze];
            r[grenze] = r[i];
            r[i] = h;
        }
    }
    int hilf = r[lo];
    r[lo] = r[grenze];
    r[grenze] = hilf;
    return grenze;
}

public static void quickSort(int[] r, int lo, int hi) {
    if (lo < hi) {
        int p = zerlege(r, lo, hi);
        quickSort(r, lo, p - 1);
        quickSort(r, p + 1, hi);
    }
}

public static void sortiereBis(int[] r, int ende) {
    if (ende <= 0) {
        return;
    }
    int m = 0;
    for (int i = 1; i <= ende; i++) {
        if (r[i] > r[m]) {
            m = i;
        }
    }
    int h = r[m];
    r[m] = r[ende];
    r[ende] = h;
    sortiereBis(r, ende - 1);
}

public static void wende(int[] r, int bis) {
    int li = 0;
    int re = bis;
    while (li < re) {
        int h = r[li];
        r[li] = r[re];
        r[re] = h;
        li++;
        re--;
    }
}

public static void pfannkuchen(int[] r, int n) {
    if (n <= 1) {
        return;
    }
    int m = 0;
    for (int i = 1; i < n; i++) {
        if (r[i] > r[m]) {
            m = i;
        }
    }
    wende(r, m);
    wende(r, n - 1);
    pfannkuchen(r, n - 1);
}

