public static void welle(int[] r, int i) {
    if (i >= r.length - 1) {
        return;
    }
    if (r[i] > r[i + 1]) {
        int h = r[i];
        r[i] = r[i + 1];
        r[i + 1] = h;
    }
    welle(r, i + 1);
}

public static void echoSort(int[] r, int n) {
